TypeScript example: 
import { RedwoodClient, RetryPolicy } from '@redwood/inference'
const client = new RedwoodClient({ retryPolicy: new RetryPolicy() })
// streaming example: EARLY_ONLY will retry only before first chunk arrives
const stream = client.generateStream({ prompt: 'Hello', idempotencyKey: 'web-88-xyz' })
for await (const chunk of stream) { console.log(chunk.text) }
